import{_ as t,o as i,c as s,ai as a}from"./chunks/framework.Ba-VnP44.js";const p=JSON.parse('{"title":"技术体系","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/index.md","filePath":"tech-system/index.md"}'),r={name:"tech-system/index.md"};function l(h,e,m,o,n,c){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="技术体系" tabindex="-1">技术体系 <a class="header-anchor" href="#技术体系" aria-label="Permalink to “技术体系”">​</a></h1><p>本站「技术体系」面向 <strong>初级 / 中级开发</strong>，用来梳理学习路线与知识地图。偏中高级的内容（分布式一致性、云原生、LLM 微调、数仓 / 大数据等）暂不下线，只在对应章节标注为选修。</p><h2 id="🏗️-核心技术栈" tabindex="-1">🏗️ 核心技术栈 <a class="header-anchor" href="#🏗️-核心技术栈" aria-label="Permalink to “🏗️ 核心技术栈”">​</a></h2><h3 id="后端技术栈" tabindex="-1">后端技术栈 <a class="header-anchor" href="#后端技术栈" aria-label="Permalink to “后端技术栈”">​</a></h3><p>沉淀判断，不是教程：<a href="/my-vitepress-site/tech-system/backend/">后端技术体系</a>。每种语言统一五篇：基础 → 核心 → 框架 → 工程 → 常见问题。</p><ul><li><strong>Java</strong>：<a href="/my-vitepress-site/tech-system/backend/java/">五篇速览</a>（含 Spring，不拆两组）</li><li><strong>Python</strong>：<a href="/my-vitepress-site/tech-system/backend/python/">五篇速览</a> · <a href="/my-vitepress-site/tech-system/backend/python/python-skill.html">技能速成</a></li><li><strong>TypeScript</strong>：<a href="/my-vitepress-site/tech-system/backend/nodejs/">五篇速览</a>（Node 运行时）</li><li><strong>Go</strong>：<a href="/my-vitepress-site/tech-system/backend/go/">五篇速览</a></li><li><strong>C#</strong>：<a href="/my-vitepress-site/tech-system/backend/csharp/">五篇速览</a></li><li><strong>后端问题</strong>：<a href="/my-vitepress-site/tech-system/backend/problems/">并发 / 库 / Redis / MQ / 分布式…</a></li></ul><p>Java 主线的深度专题另在技术体系之外维护：</p><ul><li><a href="/my-vitepress-site/java/base-overview.html">Java 语言与并发</a> — 集合、JVM、线程池、并发核心机制</li><li><a href="/my-vitepress-site/framework/overview.html">框架与中间件</a> — Spring 核心、事务、MyBatis、SpringCloud</li><li><a href="/my-vitepress-site/springboot/overview.html">SpringBoot 实践</a> — 概述与前后台管理系统技术栈</li></ul><h3 id="前端技术栈" tabindex="-1">前端技术栈 <a class="header-anchor" href="#前端技术栈" aria-label="Permalink to “前端技术栈”">​</a></h3><ul><li><a href="/my-vitepress-site/tech-system/frontend/vue-stack.html">Vue 技术栈</a> — Vue 3、组合式 API、Pinia</li><li><a href="/my-vitepress-site/tech-system/frontend/react-stack.html">React 技术栈</a> — React 18、Hooks、Redux、Next.js</li><li><a href="/my-vitepress-site/tech-system/frontend/engineering.html">前端工程化</a> — Vite、TypeScript、测试</li><li><a href="/my-vitepress-site/tech-system/frontend/mobile.html">移动端开发</a> — React Native、Flutter、PWA</li><li><a href="/my-vitepress-site/tech-system/frontend/cross-platform.html">跨平台方案</a> — Electron、Tauri、WebAssembly</li><li><a href="/my-vitepress-site/tech-system/frontend/site-refactor-job-portfolio.html">站点重构与求职作品集</a> — 本站自身的重构复盘</li></ul><h3 id="数据库与存储" tabindex="-1">数据库与存储 <a class="header-anchor" href="#数据库与存储" aria-label="Permalink to “数据库与存储”">​</a></h3><ul><li><a href="/my-vitepress-site/database/database-stack.html">数据库体系与选型</a> — 关系型 / NoSQL / NewSQL 全景</li><li><a href="/my-vitepress-site/database/relational.html">关系型数据库</a> — MySQL、PostgreSQL 优化</li><li><a href="/my-vitepress-site/database/nosql.html">NoSQL 数据库</a> — MongoDB、Redis、Elasticsearch</li><li><a href="/my-vitepress-site/database/caching.html">缓存系统</a> — 缓存策略、集群与性能</li><li>深入专题：<a href="/my-vitepress-site/database/mysql-index.html">索引原理</a> · <a href="/my-vitepress-site/database/mysql-transaction-lock.html">事务与锁</a> · <a href="/my-vitepress-site/database/sql-optimization.html">SQL 优化</a> · <a href="/my-vitepress-site/database/sharding.html">分库分表</a> · <a href="/my-vitepress-site/database/master-slave-arch.html">主从架构</a></li><li>中间件：<a href="/my-vitepress-site/redis/">Redis</a> · <a href="/my-vitepress-site/mq/overview.html">消息队列</a></li></ul><blockquote><p>数仓 / 大数据、分布式存储等偏中高级内容，暂时下线。</p></blockquote><h2 id="🔌-系统集成与通信" tabindex="-1">🔌 系统集成与通信 <a class="header-anchor" href="#🔌-系统集成与通信" aria-label="Permalink to “🔌 系统集成与通信”">​</a></h2><p>面向 <strong>多语言服务对接</strong> 与 <strong>设备通信</strong> 场景。</p><ul><li><a href="/my-vitepress-site/tech-system/integration/cross-language-interop.html">跨语言调用：方式选型</a> — HTTP / gRPC / MQ / FFI / 子进程怎么选</li><li><a href="/my-vitepress-site/tech-system/integration/http-node-python.html">HTTP：Node.js ↔ Python</a> — REST/JSON、网关与算法服务拆分</li><li><a href="/my-vitepress-site/tech-system/integration/modbus-tcp-node-plc.html">Modbus TCP：Node.js ↔ PLC</a></li><li><a href="/my-vitepress-site/tech-system/integration/modbus-tcp-python-plc.html">Modbus TCP：Python ↔ PLC</a></li><li><a href="/my-vitepress-site/tech-system/integration/s7-comm-node-plc.html">S7：Node.js ↔ PLC</a></li><li><a href="/my-vitepress-site/tech-system/integration/s7-comm-python-plc.html">S7：Python ↔ PLC</a></li></ul><h2 id="🏭-工业数字化" tabindex="-1">🏭 工业数字化 <a class="header-anchor" href="#🏭-工业数字化" aria-label="Permalink to “🏭 工业数字化”">​</a></h2><p>完整方法论 + 真实项目，见 <a href="/my-vitepress-site/tech-system/industrial-digitalization/">工业数字化实验室</a>：</p><ul><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/00-architecture-overview.html">00 架构总览</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/01-device-access.html">01 设备接入</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/02-data-platform.html">02 数据平台</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/03-realtime-system.html">03 实时系统</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/04-scada-visualization.html">04 SCADA 可视化</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/05-business-abstract.html">05 业务抽象</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/06-mes-lite.html">06 MES Lite</a></li><li><a href="/my-vitepress-site/tech-system/industrial-digitalization/07-full-system.html">07 完整系统</a></li></ul><p>配套：</p><ul><li>PLC 与采集：<a href="/my-vitepress-site/tech-system/plc/common-brands.html">常见品牌</a> · <a href="/my-vitepress-site/tech-system/plc/s7-python-data-collection.html">S7 与 Python 采集</a> · <a href="/my-vitepress-site/tech-system/plc/s7-quick-reference.html">S7 速查</a></li><li>判断记录：<a href="/my-vitepress-site/tech-system/industrial-digitalization/decisions/">判断索引</a>（为何不用 MQTT、为何不做微服务…）</li><li>动手实验：<a href="/my-vitepress-site/tech-system/industrial-digitalization/labs/">实验室索引</a> · <a href="/my-vitepress-site/tech-system/industrial-digitalization/labs/lab-001.html">Lab 001 设备采集最小闭环</a></li><li>项目推演：<a href="/my-vitepress-site/tech-system/industrial-digitalization/mini-mes/">Mini MES</a> · <a href="/my-vitepress-site/tech-system/industrial-digitalization/mini-mes/architecture.html">架构演进</a></li></ul><h2 id="🚀-devops-与运维" tabindex="-1">🚀 DevOps 与运维 <a class="header-anchor" href="#🚀-devops-与运维" aria-label="Permalink to “🚀 DevOps 与运维”">​</a></h2><ul><li><a href="/my-vitepress-site/tech-system/devops/docker.html">Docker 实战</a> — 镜像构建、多阶段构建、容器编排</li><li><a href="/my-vitepress-site/tech-system/devops/docker-desktop-windows.html">Docker Desktop（Windows）</a> — 开机自启、容器自启、Compose</li><li><a href="/my-vitepress-site/tech-system/devops/ci-cd-pipeline.html">CI/CD 流水线</a></li><li><a href="/my-vitepress-site/tech-system/devops/monitoring.html">监控与告警</a></li><li><a href="/my-vitepress-site/tech-system/devops/monitoring-observability.html">监控与可观测性</a> — Prometheus、Grafana、日志、链路追踪</li><li>面试向复盘：<a href="/my-vitepress-site/guide/devops/">DevOps 面试</a></li></ul><blockquote><p>云原生 / Service Mesh / IaC 等偏中高级内容，暂时下线。</p></blockquote><h2 id="🔐-安全" tabindex="-1">🔐 安全 <a class="header-anchor" href="#🔐-安全" aria-label="Permalink to “🔐 安全”">​</a></h2><ul><li><a href="/my-vitepress-site/tech-system/security/security-stack.html">安全体系</a></li><li><a href="/my-vitepress-site/tech-system/security/web-security.html">Web 安全</a></li></ul><h2 id="🧪-工程实践" tabindex="-1">🧪 工程实践 <a class="header-anchor" href="#🧪-工程实践" aria-label="Permalink to “🧪 工程实践”">​</a></h2><ul><li><a href="/my-vitepress-site/tech-system/practices/code-quality.html">代码质量</a></li><li><a href="/my-vitepress-site/tech-system/practices/development-practices.html">开发实践</a></li></ul><h2 id="🛠️-开发工具与资源" tabindex="-1">🛠️ 开发工具与资源 <a class="header-anchor" href="#🛠️-开发工具与资源" aria-label="Permalink to “🛠️ 开发工具与资源”">​</a></h2><ul><li><a href="/my-vitepress-site/devtools/">开发工具与环境</a> — IDE、本地数据库、容器、版本控制</li><li><a href="/my-vitepress-site/resources/">资源库</a> — 教程、书籍、官方链接、课程与网站</li></ul><h2 id="📈-行业趋势" tabindex="-1">📈 行业趋势 <a class="header-anchor" href="#📈-行业趋势" aria-label="Permalink to “📈 行业趋势”">​</a></h2><ul><li><a href="/my-vitepress-site/tech-system/trends/industry-trends.html">行业趋势观察</a></li></ul><hr><h2 id="开源拆解" tabindex="-1">开源拆解 <a class="header-anchor" href="#开源拆解" aria-label="Permalink to “开源拆解”">​</a></h2><p>以我维护的项目为主（OpenBiz、本地漫创、ModelDesk）：</p><ul><li><a href="/my-vitepress-site/open-source/">开源拆解</a></li></ul><hr><p>💡 每个技术领域会持续更新，涵盖新版本特性、最佳实践和行业趋势。</p>',38)])])}const y=t(r,[["render",l]]);export{p as __pageData,y as default};
